section.sourcecode:
csr-template-schema = { keyTypes: [ + $keyType ] ? subject: non-empty<distinguishedName> extensions: extensions }
non-empty<M> = (M) .and ({ + any => any })
mandatory-wildcard = "**" optional-wildcard = "*" wildcard = mandatory-wildcard / optional-wildcard
; regtextは、"*"と"**"を除くすべてのテキスト文字列にマッチします regtext = text .regexp "([^\*].*)|([\*][^\*].*)|([\*][\*].+)"
regtext-or-wildcard = regtext / wildcard
distinguishedName = { ? country: regtext-or-wildcard ? stateOrProvince: regtext-or-wildcard ? locality: regtext-or-wildcard ? organization: regtext-or-wildcard ? organizationalUnit: regtext-or-wildcard ? emailAddress: regtext-or-wildcard ? commonName: regtext-or-wildcard }
$keyType /= rsaKeyType $keyType /= ecdsaKeyType
rsaKeyType = { PublicKeyType: "rsaEncryption" ; OID: 1.2.840.113549.1.1.1 PublicKeyLength: rsaKeySize SignatureType: $rsaSignatureType }
rsaKeySize = uint
; SHA-256を使用するRSASSA-PKCS1-v1_5 $rsaSignatureType /= "sha256WithRSAEncryption" ; SHA-384を使用するRSASSA-PCKS1-v1_5 $rsaSignatureType /= "sha384WithRSAEncryption" ; SHA-512を使用するRSASSA-PCKS1-v1_5 $rsaSignatureType /= "sha512WithRSAEncryption" ; SHA-256、SHA-256を使用するMGF-1、32バイトのソルトを使用するRSASSA-PSS $rsaSignatureType /= "sha256WithRSAandMGF1" ; SHA-384、SHA-384を使用するMGF-1、48バイトのソルトを使用するRSASSA-PSS $rsaSignatureType /= "sha384WithRSAandMGF1" ; SHA-512、SHA-512を使用するMGF-1、64バイトのソルトを使用するRSASSA-PSS $rsaSignatureType /= "sha512WithRSAandMGF1"
ecdsaKeyType = { PublicKeyType: "id-ecPublicKey" ; OID: 1.2.840.10045.2.1 namedCurve: $ecdsaCurve SignatureType: $ecdsaSignatureType }
$ecdsaCurve /= "secp256r1" ; OID: 1.2.840.10045.3.1.7 $ecdsaCurve /= "secp384r1" ; OID: 1.3.132.0.34 $ecdsaCurve /= "secp521r1" ; OID: 1.3.132.0.3
$ecdsaSignatureType /= "ecdsa-with-SHA256" ; secp256r1と組み合わせる $ecdsaSignatureType /= "ecdsa-with-SHA384" ; secp384r1と組み合わせる $ecdsaSignatureType /= "ecdsa-with-SHA512" ; secp521r1と組み合わせる
subjectaltname = { ? DNS: [ + regtext-or-wildcard ] ? Email: [ + regtext ] ? URI: [ + regtext ] * $$subjectaltname-extension }
extensions = { ? keyUsage: [ + keyUsageType ] ? extendedKeyUsage: [ + extendedKeyUsageType ] subjectAltName: non-empty<subjectaltname> }
keyUsageType /= "digitalSignature" keyUsageType /= "nonRepudiation" keyUsageType /= "keyEncipherment" keyUsageType /= "dataEncipherment" keyUsageType /= "keyAgreement" keyUsageType /= "keyCertSign" keyUsageType /= "cRLSign" keyUsageType /= "encipherOnly" keyUsageType /= "decipherOnly"
extendedKeyUsageType /= "serverAuth" extendedKeyUsageType /= "clientAuth" extendedKeyUsageType /= "codeSigning" extendedKeyUsageType /= "emailProtection" extendedKeyUsageType /= "timeStamping" extendedKeyUsageType /= "OCSPSigning" extendedKeyUsageType /= oid
oid = text .regexp "([0-2])((\.0)|(\.[1-9][0-9]*))*"

{
  "title": "JSON Schema for the STAR Delegation CSR template",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "http://ietf.org/acme/drafts/star-delegation/csr-template",
  "$defs": {
    "distinguished-name": {
      "$id": "#distinguished-name",
      "type": "object",
      "minProperties": 1,
      "properties": {
        "country": {
          "type": "string"
        },
        "stateOrProvince": {
          "type": "string"
        },
        "locality": {
          "type": "string"
        },
        "organization": {
          "type": "string"
        },
        "organizationalUnit": {
          "type": "string"
        },
        "emailAddress": {
          "type": "string"
        },
        "commonName": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    "rsaKeyType": {
      "$id": "#rsaKeyType",
      "type": "object",
      "properties": {
        "PublicKeyType": {
          "type": "string",
          "const": "rsaEncryption"
        },
        "PublicKeyLength": {
          "type": "integer"
        },
        "SignatureType": {
          "type": "string",
          "enum": [
            "sha256WithRSAEncryption",
            "sha384WithRSAEncryption",
            "sha512WithRSAEncryption",
            "sha256WithRSAandMGF1",
            "sha384WithRSAandMGF1",
            "sha512WithRSAandMGF1"
          ]
        }
      },
      "required": [
        "PublicKeyType",
        "PublicKeyLength",
        "SignatureType"
      ],
      "additionalProperties": false
    },
    "ecdsaKeyType": {
      "$id": "#ecdsaKeyType",
      "type": "object",
      "properties": {
        "PublicKeyType": {
          "type": "string",
          "const": "id-ecPublicKey"
        },
        "namedCurve": {
          "type": "string",
          "enum": [
            "secp256r1",
            "secp384r1",
            "secp521r1"
          ]
        },
        "SignatureType": {
          "type": "string",
          "enum": [
            "ecdsa-with-SHA256",
            "ecdsa-with-SHA384",
            "ecdsa-with-SHA512"
          ]
        }
      },
      "required": [
        "PublicKeyType",
        "namedCurve",
        "SignatureType"
      ],
      "additionalProperties": false
    }
  },
  "type": "object",
  "properties": {
    "keyTypes": {
      "type": "array",
      "minItems": 1,
      "items": {
        "anyOf": [
          {
            "$ref": "#rsaKeyType"
          },
          {
            "$ref": "#ecdsaKeyType"
          }
        ]
      }
    },
    "subject": {
      "$ref": "#distinguished-name"
    },
    "extensions": {
      "type": "object",
      "properties": {
        "keyUsage": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "enum": [
              "digitalSignature",
              "nonRepudiation",
              "keyEncipherment",
              "dataEncipherment",
              "keyAgreement",
              "keyCertSign",
              "cRLSign",
              "encipherOnly",
              "decipherOnly"
            ]
          }
        },
        "extendedKeyUsage": {
          "type": "array",
          "minItems": 1,
          "items": {
            "anyOf": [
              {
                "type": "string",
                "enum": [
                  "serverAuth",
                  "clientAuth",
                  "codeSigning",
                  "emailProtection",
                  "timeStamping",
                  "OCSPSigning"
                ]
              },
              {
                "type": "string",
                "pattern": "^([0-2])((\\.0)|(\\.[1-9][0-9]*))*$",
                "description": "Used for OID values"
              }
            ]
          }
        },
        "subjectAltName": {
          "type": "object",
          "minProperties": 1,
          "properties": {
            "DNS": {
              "type": "array",
              "minItems": 1,
              "items": {
                "anyOf": [
                  {
                    "type": "string",
                    "enum": [
                      "*",
                      "**"
                    ]
                  },
                  {
                    "type": "string",
                    "format": "hostname"
                  }
                ]
              }
            },
            "Email": {
              "type": "array",
              "minItems": 1,
              "items": {
                "type": "string",
                "format": "email"
              }
            },
            "URI": {
              "type": "array",
              "minItems": 1,
              "items": {
                "type": "string",
                "format": "uri"
              }
            }
          },
          "additionalProperties": false
        }
      },
      "required": [
        "subjectAltName"
      ],
      "additionalProperties": false
    }
  },
  "required": [
    "extensions",
    "keyTypes"
  ],
  "additionalProperties": false
}
